# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: render
def render(xs, factor=10):
    return [v * factor for v in xs]

# region: fold
def fold(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) // n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: sift
def sift(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return sift(fold(render(shape(raw))))

